const baseUrl = $env.BUDGETFLOW_BASE_URL;
const apiKey = $env.BUDGETFLOW_SERVICE_API_KEY;

if (!baseUrl) {
  throw new Error("BUDGETFLOW_BASE_URL is not set. Add it as an n8n environment variable, e.g. https://budgetflow.yourdomain.com");
}
if (!apiKey) {
  throw new Error("BUDGETFLOW_SERVICE_API_KEY is not set. Generate one via POST /api/settings/service-api-key while signed in to BudgetFlow, then add it as an n8n environment variable.");
}

return [{
  json: {
    baseUrl: baseUrl.replace(/\/$/, ""),
    authHeader: `Bearer ${apiKey}`,
  },
}];
